function authSigningSecret(){const source=process.env.SESSION_SECRET||process.env.DATABASE_URL||process.env.ADMIN_PASSWORD;if(!source)throw new Error('Falta configurar SESSION_SECRET');return crypto.createHash('sha256').update(String(source)).digest();}
function createAuthToken(user){const payload=Buffer.from(JSON.stringify({username:user.username,role:user.role,name:user.name,weeklyHours:user.weeklyHours,exp:Math.floor(Date.now()/1000)+43200})).toString('base64url');const signature=crypto.createHmac('sha256',authSigningSecret()).update(payload).digest('base64url');return payload+'.'+signature;}
