app.get('/api/vendor/sheets',requireAuth,async(req,res)=>{if(req.auth.role!=='vendedor'&&req.auth.role!=='admin')return res.status(403).json({error:'Solo vendedor'});const db=await getDb();res.setHeader('Cache-Control','no-store');res.json({sheets:db.vendorSheets||createVendorSheetTemplate()})});
app.put('/api/vendor/sheets',requireAuth,async(req,res)=>{if(req.auth.role!=='vendedor'&&req.auth.role!=='admin')return res.status(403).json({error:'Solo vendedor'});try{const sheets=req.body?.sheets;if(!sheets||typeof sheets!=='object'||Array.isArray(sheets)||JSON.stringify(sheets).length>5000000)return res.status(400).json({error:'Planilla no válida o demasiado grande'});const db=await getDb();const template=createVendorSheetTemplate();for(const name of Object.keys(sheets))if(!template[name])return res.status(400).json({error:'Pestaña no válida'});for(const [name,sh] of Object.entries(sheets)){if(!sh||typeof sh!=='object'||!Number.isInteger(sh.rows)||!Number.isInteger(sh.cols)||sh.rows>150||sh.cols>40||!sh.cells||typeof sh.cells!=='object')return res.status(400).json({error:'Formato de planilla no válido'});for(const [cell,value] of Object.entries(sh.cells))if(!/^[A-Z]{1,2}[1-9][0-9]{0,2}$/.test(cell)||typeof value!=='string'&&typeof value!=='number'&&value!==null)return res.status(400).json({error:'Celda no válida'});}db.vendorSheets={...template,...sheets};await putDb(db);res.json({ok:true,sheets:db.vendorSheets})}catch(e){res.status(500).json({error:e.message})}});

app.get('/api/admin/backup',requireAuth,async(req,res)=>{if(req.auth.role!=='admin')return res.status(403).json({error:'Solo admin'});try{const db=await getDb();const backup={backupType:'control_horario_full',backupVersion:2,createdAt:new Date().toISOString(),appVersion:db.version||8,data:db};res.setHeader('Cache-Control','no-store');res.json(backup)}catch(e){res.status(500).json({error:'No se pudo crear la copia completa'})}});
app.put('/api/admin/backup/restore',requireAuth,async(req,res)=>{if(req.auth.role!=='admin')return res.status(403).json({error:'Solo admin'});try{const payload=req.body;if(payload?.backupType!=='control_horario_full'||!payload.data||!Array.isArray(payload.data.users)||!payload.data.records||typeof payload.data.records!=='object')return res.status(400).json({error:'El archivo no es una copia completa válida de Control Horario'});const incoming=JSON.parse(JSON.stringify(payload.data));const current=await getDb();const currentByUser=new Map((current.users||[]).map(u=>[u.username,u]));const seen=new Set();incoming.users=incoming.users.map(u=>{if(!u||typeof u.username!=='string'||!u.username.trim()||seen.has(u.username))throw new Error('La copia contiene usuarios no válidos o duplicados');seen.add(u.username);const existing=currentByUser.get(u.username);const hash=typeof u.passwordHash==='string'&&u.passwordHash.startsWith('$2')?u.passwordHash:existing?.passwordHash;if(!hash)throw new Error('Falta la contraseña cifrada del usuario '+u.username+'; no se ha restaurado nada');return {...u,passwordHash:hash,active:u.role==='admin'?true:u.active!==false}});if(!incoming.users.some(u=>u.role==='admin'&&u.passwordHash))return res.status(400).json({error:'La copia debe contener una cuenta administradora válida'});incoming.version=8;incoming.records=incoming.records||{};incoming.locks=incoming.locks||{};incoming.weekly=incoming.weekly||{};incoming.vacations=incoming.vacations||{};incoming.hugoErika=Array.isArray(incoming.hugoErika)?incoming.hugoErika:[];incoming.horarios=incoming.horarios&&typeof incoming.horarios==='object'?incoming.horarios:{fechaInicio:'',semanaGenerada:false,diasSemana:[],empleados:[],turnos:[],cumples:[]};incoming.balanceVisibility=incoming.balanceVisibility||{};incoming.monthLocks=incoming.monthLocks||{};incoming.personalDocuments=Array.isArray(incoming.personalDocuments)?incoming.personalDocuments:[];incoming.payrolls=Array.isArray(incoming.payrolls)?incoming.payrolls:[];incoming.auditLog=Array.isArray(incoming.auditLog)?incoming.auditLog:[];for(const u of incoming.users){incoming.records[u.username]=incoming.records[u.username]||{};incoming.locks[u.username]=incoming.locks[u.username]||{};incoming.weekly[u.username]=incoming.weekly[u.username]||[];incoming.vacations[u.username]=incoming.vacations[u.username]||[]}const restoredByUser=new Map(incoming.users.map(u=>[u.username,u]));for(const [username,u] of currentByUser){const restored=restoredByUser.get(username);if(restored&&!restored.passwordHash)restored.passwordHash=u.passwordHash}await putDb(incoming);res.json({ok:true,db:publicDb(incoming),restored:{users:incoming.users.length,records:Object.values(incoming.records).reduce((n,r)=>n+Object.keys(r||{}).length,0),vacations:Object.values(incoming.vacations).reduce((n,v)=>n+(Array.isArray(v)?v.length:0),0),payrolls:incoming.payrolls.length,hugoErika:incoming.hugoErika.length,turnos:(incoming.horarios.turnos||[]).length}})}catch(e){res.status(400).json({error:e.message||'No se pudo restaurar la copia'})}});
app.get('/api/admin/wages',requireAuth,async(req,res)=>{if(req.auth.role!=='admin')return res.status(403).json({error:'Solo admin'});try{const db=await getDb();res.setHeader('Cache-Control','no-store');res.json({wages:db.wages&&typeof db.wages==='object'?db.wages:{},wageReference:Array.isArray(db.wageReference)?db.wageReference:(Array.isArray(db.wage_reference)?db.wage_reference:[])});}catch(e){res.status(500).json({error:e.message})}});
app.put('/api/admin/wages',requireAuth,async(req,res)=>{if(req.auth.role!=='admin')return res.status(403).json({error:'Solo admin'});try{const wages=req.body?.wages,reference=req.body?.wageReference;if(!wages||typeof wages!=='object'||Array.isArray(wages)||!Array.isArray(reference))return res.status(400).json({error:'Datos de sueldos no válidos'});for(const [username,rows] of Object.entries(wages)){if(!Array.isArray(rows))return res.status(400).json({error:'Historial de sueldos no válido'});if(rows.some(x=>!x||!['hourly','special'].includes(x.type)||!Number.isFinite(Number(x.hours))||Number(x.hours)<0||!Number.isFinite(Number(x.amount))||Number(x.amount)<0))return res.status(400).json({error:'Hay horas o importes no válidos'});}const db=await getDb();db.wages=wages;db.wageReference=reference;db.wage_reference=reference;await putDb(db);res.json({ok:true,wages:db.wages,wageReference:db.wageReference});}catch(e){res.status(500).json({error:e.message})}});
app.post('/api/day-off-requests',requireAuth,async(req,res)=>{try{if(req.auth.role!=='employee')return res.status(403).json({error:'Solo los empleados pueden solicitar días libres'});const {start,end,priority,observations}=req.body||{};if(!/^\d{4}-\d{2}-\d{2}$/.test(String(start||''))||!/^\d{4}-\d{2}-\d{2}$/.test(String(end||''))||end<start)return res.status(400).json({error:'Revisa las fechas de la solicitud'});if(!['green','yellow','red'].includes(priority))return res.status(400).json({error:'Selecciona una prioridad'});const db=await getDb();db.dayOffRequests=Array.isArray(db.dayOffRequests)?db.dayOffRequests:[];const request={id:crypto.randomUUID(),username:req.auth.username,start,end,priority,observations:String(observations||'').trim().slice(0,1000),status:'pending',createdAt:new Date().toISOString()};db.dayOffRequests.push(request);await putDb(db);const employeeName=db.users.find(u=>u.username===req.auth.username)?.name||req.auth.name||req.auth.username;sendDayOffNotification(request,employeeName).catch(e=>console.error('No se pudo enviar el correo de solicitud de días libres:',e.message));res.json({ok:true,request});}catch(e){res.status(500).json({error:e.message})}});
app.delete('/api/day-off-requests/:id',requireAuth,async(req,res)=>{try{if(!['admin','employee'].includes(req.auth.role))return res.status(403).json({error:'No tienes permiso para eliminar solicitudes'});const db=await getDb();db.dayOffRequests=Array.isArray(db.dayOffRequests)?db.dayOffRequests:[];const index=db.dayOffRequests.findIndex(r=>r.id===req.params.id);if(index<0)return res.status(404).json({error:'Solicitud no encontrada'});const request=db.dayOffRequests[index];if(req.auth.role!=='admin'&&request.username!==req.auth.username)return res.status(403).json({error:'Solo puedes eliminar tus propias solicitudes'});db.dayOffRequests.splice(index,1);await putDb(db);res.json({ok:true,id:req.params.id});}catch(e){res.status(500).json({error:e.message})}});
app.put('/api/admin/day-off-requests/:id',requireAuth,async(req,res)=>{if(req.auth.role!=='admin')return res.status(403).json({error:'Solo administración'});try{const db=await getDb(),r=(db.dayOffRequests||[]).find(x=>x.id===req.params.id);if(!r)return res.status(404).json({error:'Solicitud no encontrada'});if(Array.isArray(req.body.statuses)){const allowed=['read','approved','rejected'];if(req.body.statuses.some(x=>!allowed.includes(x)))return res.status(400).json({error:'Estado no válido'});r.statuses=[...new Set(req.body.statuses)];r.status=r.statuses.includes('rejected')?'rejected':r.statuses.includes('approved')?'approved':'pending';}else{if(!['pending','approved','rejected'].includes(req.body.status))return res.status(400).json({error:'Estado no válido'});r.status=req.body.status;r.statuses=req.body.status==='pending'?[]:[req.body.status];}await putDb(db);res.json({ok:true,request:r});}catch(e){res.status(500).json({error:e.message})}});
