app.post('/api/admin/user',requireAuth,async(req,res)=>{if(req.auth.role!=='admin')return res.status(403).json({error:'Solo admin'});try{const db=await getDb(),{name,username,password,weeklyHours,active,color}=req.body;const u=String(username||'').trim().toLowerCase();if(!name||!u||!password)return res.status(400).json({error:'Faltan datos'});if(db.users.some(x=>x.username===u))return res.status(409).json({error:'Ese usuario ya existe'});db.users.push({username:u,name:String(name).trim(),role:'employee',weeklyHours:Number(weeklyHours)||40,active:active!==false,color:String(color||'#2563eb'),passwordHash:bcrypt.hashSync(String(password),12)});db.records[u]={};db.locks[u]={};db.weekly[u]=[];db.vacations[u]=[];db.balanceVisibility[u]=true;await putDb(db);res.json(publicDb(db));}catch(e){res.status(500).json({error:e.message})}});
app.put('/api/admin/user/:username',requireAuth,async(req,res)=>{if(req.auth.role!=='admin')return res.status(403).json({error:'Solo admin'});try{const db=await getDb(),u=db.users.find(x=>x.username===req.params.username);if(!u||u.role==='admin')return res.status(404).json({error:'Empleado no encontrado'});u.name=String(req.body.name||u.name).trim();u.weeklyHours=Number(req.body.weeklyHours)||40;u.active=req.body.active!==false;u.color=String(req.body.color||u.color||'#2563eb');if(req.body.password)u.passwordHash=bcrypt.hashSync(String(req.body.password),12);await putDb(db);res.json(publicDb(db));}catch(e){res.status(500).json({error:e.message})}});
app.delete('/api/admin/user/:username',requireAuth,async(req,res)=>{if(req.auth.role!=='admin')return res.status(403).json({error:'Solo admin'});try{const db=await getDb(),u=db.users.find(x=>x.username===req.params.username);if(!u||u.role==='admin')return res.status(404).json({error:'Empleado no encontrado'});db.users=db.users.filter(x=>x.username!==u.username);delete db.records[u.username];delete db.locks[u.username];delete db.weekly[u.username];delete db.vacations[u.username];delete db.balanceVisibility[u.username];await putDb(db);res.json(publicDb(db));}catch(e){res.status(500).json({error:e.message})}});


app.get('/api/horarios/summary',requireAuth,async(req,res)=>{try{const db=await getDb();const username=req.auth.role==='admin'&&req.query.username?String(req.query.username):req.auth.username;const start=String(req.query.start||'');const end=String(req.query.end||'');const h=db.horarios||{};const turnos=Array.isArray(h.turnos)?h.turnos:[];const employees=Array.isArray(h.empleados)?h.empleados:[];const emp=employees.find(e=>String(e.id)===username||String(e.username)===username);const sourceId=emp?.id||username;const inRange=t=>String(t.fecha)>=start&&String(t.fecha)<=end&&String(t.empleadoId)===String(sourceId);const minutes=turnos.filter(inRange).reduce((sum,t)=>{const [h1,m1]=String(t.horaInicio||'00:00').split(':').map(Number);const [h2,m2]=String(t.horaFin||'00:00').split(':').map(Number);const a=h1*60+(m1||0),b=h2*60+(m2||0);return sum+(b>a?b-a:0)},0);res.json({username,plannedMinutes:minutes,turnos:turnos.filter(inRange).length});}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/horarios/state',requireAuth,async(req,res)=>{try{const db=await getDb();const source=req.auth.role==='admin'?(db.horarios||{}):(db.publishedHorarios||{});const h=source.fechaInicio!==undefined?source:(db.horarios?.semanaGenerada?db.horarios:{fechaInicio:'',semanaGenerada:false,diasSemana:[],empleados:[],turnos:[],cumples:[]});const employees=(db.users||[]).filter(u=>u.role==='employee'&&u.active!==false).map(u=>({id:u.username,username:u.username,nombre:u.name,horasContratadas:Number(u.weeklyHours)||40,color:u.color||'#2563eb'}));const activeIds=new Set(employees.map(e=>String(e.id)));const oldEmployees=Array.isArray(h.empleados)?h.empleados:[];const visibleTurns=(h.turnos||[]).map(t=>{const id=String(t.empleadoId||'');if(activeIds.has(id))return t;const old=oldEmployees.find(e=>String(e.id)===id);const normName=v=>String(v||'').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').trim().toLowerCase();const oldName=normName(old?.nombre);const match=old?employees.find(e=>{const name=normName(e.nombre);return name===oldName||name.startsWith(oldName+' ')||oldName.startsWith(name+' ')}):null;return match?{...t,empleadoId:match.id}:null;}).filter(Boolean);const visibleHorarios={...h,empleados:employees.map(e=>{const normName=v=>String(v||'').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').trim().toLowerCase();const name=normName(e.nombre);const old=oldEmployees.find(x=>{const prior=normName(x.nombre);return prior===name||prior.startsWith(name+' ')||name.startsWith(prior+' ')});return {...e,legacyId:old?.id??null}}),turnos:visibleTurns};res.json({horarios:visibleHorarios,employees,user:{username:req.auth.username,role:req.auth.role,name:req.auth.name}})}catch(e){res.status(500).json({error:e.message})}});
app.put('/api/horarios/state',requireAuth,async(req,res)=>{if(req.auth.role!=='admin')return res.status(403).json({error:'Solo el administrador puede modificar el cuadrante'});try{const db=await getDb();if(!Object.prototype.hasOwnProperty.call(db,'publishedHorarios'))db.publishedHorarios=JSON.parse(JSON.stringify(db.horarios||{fechaInicio:'',semanaGenerada:false,diasSemana:[],empleados:[],turnos:[],cumples:[]}));const h=req.body||{};h.fechaInicio=String(h.fechaInicio||'');h.semanaGenerada=Boolean(h.semanaGenerada);h.diasSemana=Array.isArray(h.diasSemana)?h.diasSemana:[];h.turnos=Array.isArray(h.turnos)?h.turnos:[];h.cumples=Array.isArray(h.cumples)?h.cumples:[];const employees=(db.users||[]).filter(u=>u.role==='employee'&&u.active!==false).map(u=>({id:u.username,username:u.username,nombre:u.name,horasContratadas:Number(u.weeklyHours)||40,color:u.color||'#2563eb'}));const validIds=new Set(employees.map(e=>String(e.id)));const oldEmployees=Array.isArray(db.horarios?.empleados)?db.horarios.empleados:[];const oldByName=new Map(oldEmployees.map(e=>[String(e.nombre||'').trim().toLowerCase(),e]));h.empleados=employees.map(e=>{const old=oldByName.get(String(e.nombre).trim().toLowerCase());return {...e,id:e.id,username:e.username,legacyId:old?.id??null}});const allowedNames=new Map(employees.map(e=>[e.id,e.nombre]));h.turnos=h.turnos.map(t=>{const id=String(t.empleadoId||'');if(validIds.has(id))return {...t,empleadoId:id};const old=oldEmployees.find(e=>String(e.id)===id);const match=old?employees.find(e=>String(e.nombre||'').trim().toLowerCase()===String(old.nombre||'').trim().toLowerCase()):null;return match?{...t,empleadoId:match.id}:null;}).filter(Boolean);db.horarios=h;await putDb(db);res.json({ok:true,horarios:h,employees});}catch(e){res.status(500).json({error:e.message})}});

app.post('/api/horarios/publish',requireAuth,async(req,res)=>{if(req.auth.role!=='admin')return res.status(403).json({error:'Solo el administrador puede publicar el horario'});try{const db=await getDb(),draft=db.horarios||{};if(!draft.fechaInicio||!Array.isArray(draft.turnos)||!draft.turnos.length)return res.status(400).json({error:'Genera y guarda el nuevo horario antes de publicarlo'});db.publishedHorarios=JSON.parse(JSON.stringify({...draft,semanaGenerada:true,publishedAt:new Date().toISOString()}));await putDb(db);res.json({ok:true,publishedHorarios:db.publishedHorarios});}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/my-documents',requireAuth,async(req,res)=>{try{const db=await getDb();res.setHeader('Cache-Control','no-store');res.json((db.personalDocuments||[]).filter(d=>d.username===req.auth.username).map(({username,...d})=>d))}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/admin/documents',requireAuth,async(req,res)=>{if(req.auth.role!=='admin')return res.status(403).json({error:'Solo admin'});try{const db=await getDb();res.setHeader('Cache-Control','no-store');res.json((db.personalDocuments||[]).map(d=>({...d,employeeName:db.users.find(u=>u.username===d.username)?.name||d.username})).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)))}catch(e){res.status(500).json({error:e.message})}});
app.post('/api/admin/documents',requireAuth,async(req,res)=>{if(req.auth.role!=='admin')return res.status(403).json({error:'Solo admin'});try{const {username,title,type,month,driveUrl}=req.body,db=await getDb(),u=db.users.find(x=>x.username===username&&x.role==='employee'&&x.active!==false);if(!u)return res.status(404).json({error:'Empleado no encontrado'});if(!String(title||'').trim())return res.status(400).json({error:'Escribe el nombre del documento'});if(!['Contrato','Documento laboral','Certificado','Otro'].includes(type))return res.status(400).json({error:'Tipo de documento no válido'});let parsed;try{parsed=new URL(String(driveUrl||''))}catch(e){return res.status(400).json({error:'Enlace no válido'})}if(parsed.protocol!=='https:'||!['drive.google.com','docs.google.com'].includes(parsed.hostname))return res.status(400).json({error:'Usa un enlace HTTPS de Google Drive'});db.personalDocuments=Array.isArray(db.personalDocuments)?db.personalDocuments:[];const doc={id:crypto.randomUUID(),username:u.username,title:String(title).trim().slice(0,160),type,month:/^\d{4}-\d{2}$/.test(String(month||''))?String(month):'',driveUrl:parsed.toString(),createdAt:new Date().toISOString()};db.personalDocuments.push(doc);await putDb(db);res.json({ok:true,document:{...doc,employeeName:u.name}})}catch(e){res.status(500).json({error:e.message})}});
app.put('/api/admin/documents/:id',requireAuth,async(req,res)=>{if(req.auth.role!=='admin')return res.status(403).json({error:'Solo admin'});try{const db=await getDb(),d=(db.personalDocuments||[]).find(x=>x.id===req.params.id);if(!d)return res.status(404).json({error:'Documento no encontrado'});const title=String(req.body.title||'').trim(),type=String(req.body.type||''),month=String(req.body.month||''),driveUrl=String(req.body.driveUrl||'');if(!title)return res.status(400).json({error:'Escribe el nombre del documento'});if(!['Contrato','Documento laboral','Certificado','Otro'].includes(type))return res.status(400).json({error:'Tipo de documento no válido'});let parsed;try{parsed=new URL(driveUrl)}catch(e){return res.status(400).json({error:'Enlace no válido'})}if(parsed.protocol!=='https:'||!['drive.google.com','docs.google.com'].includes(parsed.hostname))return res.status(400).json({error:'Usa un enlace HTTPS de Google Drive'});if(month&&!/^\d{4}-\d{2}$/.test(month))return res.status(400).json({error:'Periodo no válido'});d.title=title.slice(0,160);d.type=type;d.month=month;d.driveUrl=parsed.toString();await putDb(db);res.json({ok:true,document:d})}catch(e){res.status(500).json({error:e.message})}});
app.delete('/api/admin/documents/:id',requireAuth,async(req,res)=>{if(req.auth.role!=='admin')return res.status(403).json({error:'Solo admin'});try{const db=await getDb();const before=(db.personalDocuments||[]).length;db.personalDocuments=(db.personalDocuments||[]).filter(d=>d.id!==req.params.id);if(db.personalDocuments.length===before)return res.status(404).json({error:'Documento no encontrado'});await putDb(db);res.json({ok:true})}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/payrolls',requireAuth,async(req,res)=>{try{const db=await getDb();const all=ensurePayrolls(db);const rows=req.auth.role==='admin'?all:all.filter(x=>x.username===req.auth.username);const safe=[];for(const p of rows){const {driveFileId,...row}=p;if(!row.driveUrl&&driveFileId){try{const {drive}=driveConfig();const meta=await drive.files.get({fileId:driveFileId,fields:'webViewLink'});row.driveUrl=meta.data.webViewLink||'';}catch(e){row.driveUrl='';}}safe.push(row)}res.json(safe);}catch(e){res.status(500).json({error:e.message})}});
app.post('/api/admin/payroll',requireAuth,async(req,res)=>{if(req.auth.role!=='admin')return res.status(403).json({error:'Solo admin'});try{const {username,month,amount,driveUrl}=req.body;const db=await getDb();const u=db.users.find(x=>x.username===username&&x.role==='employee'&&x.active!==false);if(!u)return res.status(404).json({error:'Empleado no encontrado'});if(!/^\d{4}-\d{2}$/.test(String(month||'')))return res.status(400).json({error:'Mes no válido'});let parsed;try{parsed=new URL(String(driveUrl||''));}catch(e){return res.status(400).json({error:'Enlace de Google Drive no válido'});}if(parsed.protocol!=='https:'||!['drive.google.com','docs.google.com'].includes(parsed.hostname))return res.status(400).json({error:'Usa un enlace HTTPS de Google Drive'});if(amount!==null&&amount!==undefined&&amount!==''&&(!Number.isFinite(Number(amount))||Number(amount)<0))return res.status(400).json({error:'Importe no válido'});const payroll={id:crypto.randomUUID(),username:u.username,employeeName:u.name,month:String(month),driveUrl:parsed.toString(),createdAt:new Date().toISOString()};if(amount!==null&&amount!==undefined&&amount!=='')payroll.amount=Number(amount);ensurePayrolls(db).push(payroll);await putDb(db);res.json({ok:true,payroll});}catch(e){console.error(e);res.status(500).json({error:e.message})}});
app.get('/api/payroll/:id',requireAuth,async(req,res)=>{try{const db=await getDb();const p=ensurePayrolls(db).find(x=>x.id===req.params.id);if(!p)return res.status(404).json({error:'Nómina no encontrada'});if(req.auth.role!=='admin'&&p.username!==req.auth.username)return res.status(403).json({error:'No tienes permiso para ver esta nómina'});const {drive}=driveConfig();const meta=await drive.files.get({fileId:p.driveFileId,fields:'name,mimeType'});res.setHeader('Content-Type','application/pdf');res.setHeader('Content-Disposition','inline; filename="'+String(p.filename).replace(/"/g,'')+'"');const file=await drive.files.get({fileId:p.driveFileId}, {responseType:'stream'});file.data.pipe(res);}catch(e){console.error(e);res.status(500).json({error:'No se pudo abrir la nómina'})}});
app.put('/api/admin/payroll/:id',requireAuth,async(req,res)=>{if(req.auth.role!=='admin')return res.status(403).json({error:'Solo admin'});try{const db=await getDb(),p=ensurePayrolls(db).find(x=>x.id===req.params.id);if(!p)return res.status(404).json({error:'Nómina no encontrada'});const month=String(req.body.month||''),driveUrl=String(req.body.driveUrl||'');if(!/^\d{4}-\d{2}$/.test(month))return res.status(400).json({error:'Mes no válido'});let parsed;try{parsed=new URL(driveUrl)}catch(e){return res.status(400).json({error:'Enlace de Google Drive no válido'})}if(parsed.protocol!=='https:'||!['drive.google.com','docs.google.com'].includes(parsed.hostname))return res.status(400).json({error:'Usa un enlace HTTPS de Google Drive'});p.month=month;p.driveUrl=parsed.toString();if(req.body.amount===null||req.body.amount==='')delete p.amount;else if(!Number.isFinite(Number(req.body.amount))||Number(req.body.amount)<0)return res.status(400).json({error:'Importe no válido'});else p.amount=Number(req.body.amount);await putDb(db);res.json({ok:true,payroll:p})}catch(e){res.status(500).json({error:e.message})}});
app.delete('/api/admin/payroll/:id',requireAuth,async(req,res)=>{if(req.auth.role!=='admin')return res.status(403).json({error:'Solo admin'});try{const db=await getDb();const idx=ensurePayrolls(db).findIndex(x=>x.id===req.params.id);if(idx<0)return res.status(404).json({error:'Nómina no encontrada'});const p=db.payrolls[idx];if(p.driveFileId){const {drive}=driveConfig();try{await drive.files.delete({fileId:p.driveFileId});}catch(e){if(e.code!==404)throw e}}db.payrolls.splice(idx,1);await putDb(db);res.json({ok:true});}catch(e){res.status(500).json({error:e.message})}});

app.get('*',(req,res)=>res.sendFile(require('path').join(__dirname,'index.html')));
init().then(()=>app.listen(process.env.PORT||10000,'0.0.0.0',()=>console.log('Control horario running'))).catch(e=>{console.error(e);process.exit(1)});
